Definition g8f_exit (ra sp gp tp t0 t1 t2 s0 s1 a0 a4 a5 a6 a7 s4 s6 s9 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (DR dn : Z) : machine_state -> Prop :=
  fun ms' => exists (a1' a2' a3' s2' s3' s5' s7' s8' s10' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1' a2' a3' a4 a5 a6 a7 s2' s3' s4 s5' s6 s7' s9 s10' s11 s8' t3 t4 t5 t6)
             F (Z_to_bv 64 0x12d75c) fc None m' (seg_rom asegs)
    /\ munch [(DR, DR + dn)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

(* [comment removed for export] *)
Lemma g8f_rows : forall (k : nat) (i : Z)
    (ra gp tp t0 t1 t2 s0 s1 a0 a3 a4 a7 s2 s4 s5 s6 s8 t3 t4 t6 : word) F fc (m : mem)
    (sp dh swpl dwpl PS1 PD1 SR sn DR dn ft5 fa6 : Z),
  Z.of_nat k = dh - i -> 0 <= i -> (1 <= k)%nat -> dh <= 20000 ->
  0 < swpl <= 2^20 -> 0 < dwpl <= 2^20 ->
  0 < SR -> SR mod 4 = 0 -> SR + sn <= 2^47 -> 0 < DR -> DR mod 4 = 0 -> DR + dn <= 2^47 -> PS1 mod 4 = 0 -> PD1 mod 4 = 0 ->
  (DR + dn <= 0x7fff7000 \/ 0x10007fff8000 <= DR) ->
  0 <= sp -> sp + 144 <= 2^47 -> (DR + dn <= sp \/ sp + 144 <= DR) ->
  0 <= ft5 < 2 -> 0 <= fa6 < 2 ->
  (forall i', 0 <= i' < dh -> SR <= PS1 + 4 * (swpl * i') /\ PS1 + 4 * (swpl * i') + 4 <= SR + sn) ->
  (ft5 = 1 -> fa6 = 0 -> forall i', 0 <= i' < dh -> PS1 + 4 * (swpl * i') + 8 <= SR + sn) ->
  (forall i', 0 <= i' < dh -> DR <= PD1 + 4 * (dwpl * i') /\ PD1 + 4 * (dwpl * i') + 4 <= DR + dn) ->
  wr_at asegs m SR sn -> acc asegs m SR sn -> wr_at asegs m DR dn -> acc asegs m DR dn -> mem_inv asegs m ->
  evt asegs (g8f_exit ra (Z_to_bv 64 sp) gp tp t0 t1 t2 s0 s1 a0 a4 (Z_to_bv 64 2147450880) (Z_to_bv 64 fa6) a7 s4 s6 (Z_to_bv 64 (swpl * 4)) (Z_to_bv 64 (dwpl * 4))
               t3 t4 (Z_to_bv 64 ft5) t6 F fc m DR dn)
    (MS (mkR ra (Z_to_bv 64 sp) gp tp t0 t1 t2 s0 s1 a0 (Z_to_bv 64 (PD1 + 4 * (dwpl * i))) (Z_to_bv 64 (PS1 + 4 * (swpl * i))) a3 a4 (Z_to_bv 64 2147450880) (Z_to_bv 64 fa6) a7 s2 (Z_to_bv 64 (PD1 + 4 * (dwpl * i))) s4 s5 s6 (Z_to_bv 64 (dh - i)) (Z_to_bv 64 (swpl * 4)) (Z_to_bv 64 (PS1 + 4 * (swpl * i) + 4)) (Z_to_bv 64 (dwpl * 4)) s8 t3 t4 (Z_to_bv 64 ft5) t6)
