Definition g8l_exit (sp gp tp t0 t1 t2 a3 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t4 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (DR dn : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' s0' s1' a0' a1' a2' s2' t3' t5' : word) (m' : mem),
    ms' = MS (mkR ra' sp gp tp t0 t1 t2 s1' s2' a0' a1' a2' a3 a4 a5 a6 a7 t4 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t5' t6 s0')
             F (Z_to_bv 64 0x12de9c) fc None m' (seg_rom asegs)
    /\ munch [(DR, DR + dn)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

(* [comment removed for export] *)
Lemma g8l_rows : forall (k : nat) (i : Z)
    (gp tp t0 t1 t2 s0 s1 a2 a3 a6 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t4 : word) F fc (m : mem)
    (sp dh swpl dwpl PSL PDL SR sn DR dn ft6 : Z),
  Z.of_nat k = dh - i -> 0 <= i -> (1 <= k)%nat -> dh <= 20000 ->
  0 < swpl <= 2^20 -> 0 < dwpl <= 2^20 ->
  0 < SR -> SR mod 4 = 0 -> SR + sn <= 2^47 -> 0 < DR -> DR mod 4 = 0 -> DR + dn <= 2^47 -> PSL mod 4 = 0 -> PDL mod 4 = 0 ->
  (DR + dn <= 0x7fff7000 \/ 0x10007fff8000 <= DR) ->
