Lemma g8w_words : forall (k : nat) (j : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a0 a3 a4 a7 s2 s3 s4 s5 s6 s9 s10 s11 t3 t4 t5 t6 : word) F fc (m : mem) (SA DA n : Z),
